#include <vector>

class Solution {
public:
    void inorder(TreeNode* node, std::vector<int>& out) {
        if (!node) return;
        inorder(node->left, out);
        out.push_back(node->val);
        inorder(node->right, out);
    }
    std::vector<int> getAllElements(TreeNode* root1, TreeNode* root2) {
        std::vector<int> l1, l2;
        inorder(root1, l1);
        inorder(root2, l2);
        std::vector<int> res;
        int i = 0, j = 0;
        while (i < (int)l1.size() && j < (int)l2.size()) {
            if (l1[i] <= l2[j]) res.push_back(l1[i++]);
            else res.push_back(l2[j++]);
        }
        while (i < (int)l1.size()) res.push_back(l1[i++]);
        while (j < (int)l2.size()) res.push_back(l2[j++]);
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> getAllElements(TreeNode root1, TreeNode root2) {
        List<Integer> l1 = new ArrayList<>();
        List<Integer> l2 = new ArrayList<>();
        inorder(root1, l1);
        inorder(root2, l2);
        List<Integer> res = new ArrayList<>(l1.size() + l2.size());
        int i = 0, j = 0;
        while (i < l1.size() && j < l2.size()) {
            if (l1.get(i) <= l2.get(j)) res.add(l1.get(i++));
            else res.add(l2.get(j++));
        }
        while (i < l1.size()) res.add(l1.get(i++));
        while (j < l2.size()) res.add(l2.get(j++));
        return res;
    }
    private void inorder(TreeNode node, List<Integer> out) {
        if (node == null) return;
        inorder(node.left, out);
        out.add(node.val);
        inorder(node.right, out);
    }
}

